CREATE SCHEMA IF NOT EXISTS "public";

CREATE TABLE "Categories" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Name" character varying(40) NOT NULL,
    "Icon" character varying(30) NOT NULL,
    "AccentColor" character varying(10) NOT NULL,
    "Description" character varying(160) NOT NULL,
    "SortOrder" integer NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedAtUtc" timestamp with time zone NOT NULL,
    "UpdatedAtUtc" timestamp with time zone NULL,
    CONSTRAINT "PK_Categories" PRIMARY KEY ("Id")
);

CREATE TABLE "Users" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "FullName" character varying(80) NOT NULL,
    "Username" character varying(40) NOT NULL,
    "PasswordHash" character varying(300) NOT NULL,
    "Role" character varying(20) NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedAtUtc" timestamp with time zone NOT NULL,
    "LastLoginUtc" timestamp with time zone NULL,
    CONSTRAINT "PK_Users" PRIMARY KEY ("Id")
);

CREATE TABLE "Products" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "CategoryId" integer NOT NULL,
    "Name" character varying(80) NOT NULL,
    "Description" character varying(240) NOT NULL,
    "Price" numeric(10,2) NOT NULL,
    "ImagePath" character varying(200) NOT NULL,
    "Badge" character varying(24) NOT NULL,
    "IsRecommended" boolean NOT NULL,
    "SortOrder" integer NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedAtUtc" timestamp with time zone NOT NULL,
    "UpdatedAtUtc" timestamp with time zone NULL,
    CONSTRAINT "PK_Products" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Products_Categories_CategoryId" FOREIGN KEY ("CategoryId")
        REFERENCES "Categories" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Orders" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Code" character varying(24) NOT NULL,
    "StudentName" character varying(60) NOT NULL,
    "ClassName" character varying(40) NOT NULL,
    "Note" character varying(240) NOT NULL,
    "Status" character varying(24) NOT NULL,
    "TotalAmount" numeric(12,2) NOT NULL,
    "CreatedAtUtc" timestamp with time zone NOT NULL,
    "UpdatedAtUtc" timestamp with time zone NOT NULL,
    "CompletedAtUtc" timestamp with time zone NULL,
    "MarkedByUserId" integer NULL,
    CONSTRAINT "PK_Orders" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Orders_Users_MarkedByUserId" FOREIGN KEY ("MarkedByUserId")
        REFERENCES "Users" ("Id") ON DELETE SET NULL
);

CREATE TABLE "OrderItems" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "OrderId" integer NOT NULL,
    "ProductId" integer NULL,
    "ProductName" character varying(80) NOT NULL,
    "UnitPrice" numeric(10,2) NOT NULL,
    "Quantity" integer NOT NULL,
    "LineTotal" numeric(12,2) NOT NULL,
    CONSTRAINT "PK_OrderItems" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_OrderItems_Orders_OrderId" FOREIGN KEY ("OrderId")
        REFERENCES "Orders" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_OrderItems_Products_ProductId" FOREIGN KEY ("ProductId")
        REFERENCES "Products" ("Id") ON DELETE SET NULL
);

CREATE UNIQUE INDEX "IX_Categories_Name" ON "Categories" ("Name");
CREATE INDEX "IX_Categories_SortOrder" ON "Categories" ("SortOrder");
CREATE UNIQUE INDEX "IX_Users_Username" ON "Users" ("Username");
CREATE INDEX "IX_Products_CategoryId" ON "Products" ("CategoryId");
CREATE INDEX "IX_Products_IsActive" ON "Products" ("IsActive");
CREATE INDEX "IX_Products_Name" ON "Products" ("Name");
CREATE UNIQUE INDEX "IX_Orders_Code" ON "Orders" ("Code");
CREATE INDEX "IX_Orders_CreatedAtUtc" ON "Orders" ("CreatedAtUtc");
CREATE INDEX "IX_Orders_MarkedByUserId" ON "Orders" ("MarkedByUserId");
CREATE INDEX "IX_Orders_Status" ON "Orders" ("Status");
CREATE INDEX "IX_OrderItems_OrderId" ON "OrderItems" ("OrderId");
CREATE INDEX "IX_OrderItems_ProductId" ON "OrderItems" ("ProductId");

CREATE TABLE "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

